 using(tenant_id=current_tenant_id() and coalesce(current_user_role(),'') in ('owner','admin'));
create policy learn_work_delay_cancellations_read on public.learn_work_delay_cancellations for select to authenticated
 using(tenant_id=current_tenant_id() and coalesce(current_user_role(),'') in ('owner','admin'));
